-- Publish the first verified question bank for every seeded category.
-- Each category has two questions at each level so start_assessment can
-- produce the required ten-question snapshot.
insert into public.assessment_questions(
  category_id, level, topic, question, options, correct_option, explanation, is_active
)
select c.id, q.level, q.topic, q.question, q.options::jsonb, q.correct_option, q.explanation, true
from public.categories c
join (values
  ('philosophy',1,'철학의 질문','철학적 질문의 특징으로 가장 알맞은 것은 무엇인가요?','[{"id":"A","text":"정답을 빠르게 외우는 것"},{"id":"B","text":"근거를 묻고 개념을 성찰하는 것"},{"id":"C","text":"측정 가능한 수치만 다루는 것"},{"id":"D","text":"개인의 취향을 판단하는 것"}]','B','철학은 당연하게 여긴 전제와 개념을 근거를 통해 다시 살펴봅니다.'),
  ('philosophy',1,'논증','논증에서 결론을 뒷받침하는 문장은 무엇인가요?','[{"id":"A","text":"전제"},{"id":"B","text":"비유"},{"id":"C","text":"감탄"},{"id":"D","text":"주제"}]','A','전제는 결론이 성립하도록 이유를 제공하는 문장입니다.'),
  ('philosophy',2,'인식론','경험론이 지식의 형성에서 특히 중요하게 보는 것은 무엇인가요?','[{"id":"A","text":"감각과 경험"},{"id":"B","text":"출생 신분"},{"id":"C","text":"권위자의 명령"},{"id":"D","text":"우연한 추측"}]','A','경험론은 감각 경험과 관찰을 지식의 중요한 원천으로 봅니다.'),
  ('philosophy',2,'윤리','공리주의가 행위의 옳고 그름을 판단할 때 중시하는 것은 무엇인가요?','[{"id":"A","text":"행위자의 혈통"},{"id":"B","text":"결과와 전체 행복"},{"id":"C","text":"관습의 나이"},{"id":"D","text":"의도의 비밀스러움"}]','B','공리주의는 행위가 낳는 결과와 전체의 행복 또는 효용을 중시합니다.'),
  ('philosophy',3,'정의','정의로운 분배를 논할 때 반드시 함께 검토해야 할 것은 무엇인가요?','[{"id":"A","text":"분배 기준과 대상의 필요"},{"id":"B","text":"가장 큰 숫자 하나"},{"id":"C","text":"결과를 숨기는 방법"},{"id":"D","text":"논쟁의 목소리 크기"}]','A','분배의 정당성은 어떤 기준으로 누구에게 어떻게 나누는지와 관련됩니다.'),
  ('philosophy',3,'자유의지','결정론에 대한 설명으로 알맞은 것은 무엇인가요?','[{"id":"A","text":"모든 사건은 아무 원인도 없다"},{"id":"B","text":"사건은 이전 조건과 법칙의 영향을 받는다"},{"id":"C","text":"선택은 항상 무작위다"},{"id":"D","text":"도덕 판단은 불가능하다"}]','B','결정론은 사건이 선행 조건과 자연 법칙에 의해 정해진다고 보는 입장입니다.'),
  ('philosophy',4,'과학철학','반증 가능성이 과학 이론의 조건으로 제시되는 이유는 무엇인가요?','[{"id":"A","text":"어떤 관찰로도 틀릴 수 없게 하려고"},{"id":"B","text":"경험적 검사를 통해 틀릴 가능성을 열어 두려고"},{"id":"C","text":"권위를 강화하려고"},{"id":"D","text":"수학을 없애려고"}]','B','반증 가능성은 관찰과 실험으로 이론이 틀릴 수 있는지를 검사할 수 있게 합니다.'),
  ('philosophy',4,'언어와 의미','언어의 의미를 해석할 때 문맥이 중요한 이유는 무엇인가요?','[{"id":"A","text":"같은 표현도 사용 상황에 따라 뜻이 달라질 수 있어서"},{"id":"B","text":"문맥은 문장을 삭제해서"},{"id":"C","text":"모든 단어가 한 뜻만 가져서"},{"id":"D","text":"문맥이 사실을 자동으로 만들어서"}]','A','표현의 의미는 사용된 상황과 다른 문장과의 관계에 따라 달라질 수 있습니다.'),
  ('philosophy',5,'윤리적 딜레마','윤리적 딜레마를 분석할 때 가장 먼저 해야 할 일은 무엇인가요?','[{"id":"A","text":"선택지를 하나 숨기는 것"},{"id":"B","text":"관련 가치와 이해관계자를 구분하는 것"},{"id":"C","text":"결과를 미리 단정하는 것"},{"id":"D","text":"감정만 기록하는 것"}]','B','딜레마는 충돌하는 가치와 영향을 받는 사람을 명확히 해야 비교할 수 있습니다.'),
  ('philosophy',5,'정당화','서로 다른 철학적 입장을 공정하게 비교하는 방법은 무엇인가요?','[{"id":"A","text":"한 입장을 약하게 요약하는 것"},{"id":"B","text":"각 입장의 전제·논거·반례를 함께 검토하는 것"},{"id":"C","text":"유명한 사람의 입장만 따르는 것"},{"id":"D","text":"결론만 나열하는 것"}]','B','공정한 비교는 각 입장의 전제와 추론, 강점과 반례를 같은 기준으로 살핍니다.'),
  ('psychology',1,'심리학의 대상','심리학이 주로 연구하는 것은 무엇인가요?','[{"id":"A","text":"행동과 정신 과정"},{"id":"B","text":"별의 궤도만"},{"id":"C","text":"암석의 나이만"},{"id":"D","text":"환율의 변동만"}]','A','심리학은 행동과 사고·감정 같은 정신 과정을 과학적으로 연구합니다.'),
  ('psychology',1,'기억','새로운 정보를 반복해서 떠올리는 학습 방법은 무엇인가요?','[{"id":"A","text":"인출 연습"},{"id":"B","text":"무관심"},{"id":"C","text":"수면 박탈"},{"id":"D","text":"정보 삭제"}]','A','인출 연습은 저장한 정보를 스스로 꺼내 보며 기억을 강화하는 방법입니다.'),
  ('psychology',2,'조건형성','고전적 조건형성에서 중성 자극이 학습 뒤 어떤 역할을 하게 되나요?','[{"id":"A","text":"조건 자극"},{"id":"B","text":"무조건 반응"},{"id":"C","text":"표본 집단"},{"id":"D","text":"측정 오차"}]','A','중성 자극이 자연스러운 자극과 반복 결합되면 조건 자극이 될 수 있습니다.'),
  ('psychology',2,'발달','발달심리학에서 종단 연구의 특징은 무엇인가요?','[{"id":"A","text":"같은 사람을 시간에 따라 관찰한다"},{"id":"B","text":"한 시점의 사람만 비교한다"},{"id":"C","text":"실험을 전혀 하지 않는다"},{"id":"D","text":"자료를 무작위로 버린다"}]','A','종단 연구는 동일한 개인이나 집단의 변화를 시간에 따라 추적합니다.'),
  ('psychology',3,'인지 편향','확증편향은 어떤 경향을 뜻하나요?','[{"id":"A","text":"자신의 믿음과 맞는 정보만 더 받아들이는 경향"},{"id":"B","text":"모든 정보를 같은 비중으로 검토하는 태도"},{"id":"C","text":"기억을 전혀 사용하지 않는 상태"},{"id":"D","text":"무작위로 결정을 내리는 규칙"}]','A','확증편향은 기존 믿음에 부합하는 증거를 선택적으로 찾고 해석하는 경향입니다.'),
  ('psychology',3,'사회심리','방관자 효과를 줄이는 데 도움이 되는 행동은 무엇인가요?','[{"id":"A","text":"도움을 요청할 사람을 구체적으로 지목한다"},{"id":"B","text":"아무에게도 말하지 않는다"},{"id":"C","text":"상황을 촬영하기만 한다"},{"id":"D","text":"책임을 모두에게 분산한다"}]','A','특정인을 지목해 도움을 요청하면 책임 확산을 줄이고 행동을 촉진할 수 있습니다.'),
  ('psychology',4,'연구 방법','상관관계만으로 인과관계를 단정하기 어려운 이유는 무엇인가요?','[{"id":"A","text":"제3의 변인이나 역인과 가능성이 있기 때문"},{"id":"B","text":"상관은 항상 0이기 때문"},{"id":"C","text":"자료가 숫자일 수 없기 때문"},{"id":"D","text":"실험은 결과를 만들지 않기 때문"}]','A','두 변수의 동반 변화만으로는 제3의 원인이나 원인 방향을 배제할 수 없습니다.'),
  ('psychology',4,'정서','인지 재평가가 정서 조절에 쓰이는 방식은 무엇인가요?','[{"id":"A","text":"상황의 의미를 다른 관점에서 해석한다"},{"id":"B","text":"감정을 무조건 억압한다"},{"id":"C","text":"모든 상황을 회피한다"},{"id":"D","text":"타인의 감정을 부정한다"}]','A','인지 재평가는 상황에 부여한 의미를 바꾸어 정서 반응을 조절합니다.'),
  ('psychology',5,'측정','심리검사의 신뢰도와 타당도의 관계로 알맞은 것은 무엇인가요?','[{"id":"A","text":"신뢰도는 일관성, 타당도는 측정하려는 것을 재는 정도다"},{"id":"B","text":"둘은 항상 같은 뜻이다"},{"id":"C","text":"타당도는 표본 크기만 뜻한다"},{"id":"D","text":"신뢰도는 결과의 도덕성을 뜻한다"}]','A','신뢰도는 측정의 일관성이고 타당도는 의도한 구성개념을 제대로 측정하는 정도입니다.'),
  ('psychology',5,'개입 평가','심리 개입의 효과를 평가할 때 대조군이 필요한 이유는 무엇인가요?','[{"id":"A","text":"시간 경과나 자연 회복 같은 다른 설명을 비교하려고"},{"id":"B","text":"참여자를 줄이려고"},{"id":"C","text":"결과를 미리 정하려고"},{"id":"D","text":"질문을 없애려고"}]','A','대조군은 개입 외 요인이 결과에 미친 영향을 가늠하는 기준을 제공합니다.'),
  ('society',1,'사회 구조','사회학에서 사회 구조는 무엇을 가리키나요?','[{"id":"A","text":"반복되는 관계와 제도적 틀"},{"id":"B","text":"개인의 하루 기분만"},{"id":"C","text":"자연환경의 온도만"},{"id":"D","text":"한 번의 우연한 사건"}]','A','사회 구조는 개인과 집단의 행동에 영향을 주는 지속적인 관계와 제도입니다.'),
  ('society',1,'규범','사회 규범의 의미로 알맞은 것은 무엇인가요?','[{"id":"A","text":"공동체에서 기대되는 행동 기준"},{"id":"B","text":"개인의 혈액형"},{"id":"C","text":"법정의 판결문만"},{"id":"D","text":"자연법칙의 공식"}]','A','규범은 특정 상황에서 어떻게 행동해야 하는지에 대한 사회적 기대입니다.'),
  ('society',2,'사회화','사회화가 이루어지는 대표적인 기관은 무엇인가요?','[{"id":"A","text":"가족과 학교"},{"id":"B","text":"기상 관측소만"},{"id":"C","text":"교통 신호만"},{"id":"D","text":"무인 기계만"}]','A','가족과 학교는 가치·규범·역할을 배우는 핵심 사회화 기관입니다.'),
  ('society',2,'인구','인구의 고령화가 빠르게 진행될 때 나타날 수 있는 변화는 무엇인가요?','[{"id":"A","text":"노년 부양과 의료 수요의 증가"},{"id":"B","text":"모든 인구의 동일한 소득"},{"id":"C","text":"교육 수요의 완전한 소멸"},{"id":"D","text":"도시가 모두 사라짐"}]','A','고령 인구가 늘면 연금·의료·돌봄과 노동시장에 대한 수요와 부담이 변합니다.'),
  ('society',3,'불평등','기회의 불평등을 설명하는 사례는 무엇인가요?','[{"id":"A","text":"출신에 따라 교육 접근성이 크게 달라지는 것"},{"id":"B","text":"동일한 규칙으로 줄을 서는 것"},{"id":"C","text":"날씨가 바뀌는 것"},{"id":"D","text":"모두가 같은 책을 읽는 것"}]','A','기회 불평등은 교육·취업 등 선택의 기회가 집단별로 다르게 분포하는 현상입니다.'),
  ('society',3,'도시화','도시화의 일반적 의미는 무엇인가요?','[{"id":"A","text":"인구와 기능이 도시 지역에 집중되는 과정"},{"id":"B","text":"모든 지역의 인구가 같아지는 과정"},{"id":"C","text":"농업 생산이 항상 증가하는 현상"},{"id":"D","text":"국경이 사라지는 현상"}]','A','도시화는 인구·산업·서비스가 도시로 집중되고 도시적 생활양식이 확산되는 과정입니다.'),
  ('society',4,'사회 이동','세대 간 사회 이동은 무엇을 비교하나요?','[{"id":"A","text":"부모 세대와 자녀 세대의 사회적 위치"},{"id":"B","text":"아침과 저녁의 기온"},{"id":"C","text":"서로 다른 행성의 크기"},{"id":"D","text":"한 사람의 취미 변화만"}]','A','세대 간 이동은 부모와 자녀의 계층·직업 등 사회적 위치를 비교합니다.'),
  ('society',4,'사회 자본','사회 자본이 개인과 공동체에 줄 수 있는 효과는 무엇인가요?','[{"id":"A","text":"신뢰와 네트워크를 통한 협력 촉진"},{"id":"B","text":"모든 갈등의 자동 해결"},{"id":"C","text":"정보의 완전한 차단"},{"id":"D","text":"법률의 폐지"}]','A','신뢰와 관계망은 정보 공유와 협력을 가능하게 하지만 효과가 항상 자동적인 것은 아닙니다.'),
  ('society',5,'정책 평가','사회정책의 효과를 평가할 때 분배를 함께 보는 이유는 무엇인가요?','[{"id":"A","text":"평균 효과와 수혜·부담의 집단별 차이가 다를 수 있어서"},{"id":"B","text":"평균값이 존재하지 않아서"},{"id":"C","text":"정책은 숫자로 평가할 수 없어서"},{"id":"D","text":"모든 집단의 이해가 같아서"}]','A','정책은 평균적으로 효과가 있어도 혜택과 비용이 집단별로 다르게 배분될 수 있습니다.'),
  ('society',5,'사회 변화','기술 변화가 사회에 미치는 영향을 분석할 때 적절한 접근은 무엇인가요?','[{"id":"A","text":"기술 자체와 제도·이용자의 상호작용을 함께 본다"},{"id":"B","text":"기술만 원인이라고 단정한다"},{"id":"C","text":"사용자의 선택을 무시한다"},{"id":"D","text":"변화의 결과를 조사하지 않는다"}]','A','기술의 영향은 기술적 특성뿐 아니라 제도와 사용 방식이 함께 구성합니다.'),
  ('history',1,'사료','역사 연구에서 사료는 무엇인가요?','[{"id":"A","text":"과거를 이해하는 데 사용하는 자료"},{"id":"B","text":"미래를 예언하는 주문"},{"id":"C","text":"현재의 감정만"},{"id":"D","text":"역사와 무관한 숫자"}]','A','사료에는 문서·유물·구술 등 과거를 살피는 데 활용되는 자료가 포함됩니다.'),
  ('history',1,'연대','연대기를 작성할 때 가장 중요한 것은 무엇인가요?','[{"id":"A","text":"사건의 시간 순서를 확인하는 것"},{"id":"B","text":"인물의 외모를 비교하는 것"},{"id":"C","text":"현재의 가치만 적용하는 것"},{"id":"D","text":"자료를 무작위로 배열하는 것"}]','A','연대기는 사건이 일어난 시간과 순서를 정리해 변화의 흐름을 파악하게 합니다.'),
  ('history',2,'사료 비판','사료의 작성 목적을 확인하는 이유는 무엇인가요?','[{"id":"A","text":"내용의 관점과 한계를 파악하려고"},{"id":"B","text":"자료를 모두 폐기하려고"},{"id":"C","text":"작성자의 이름을 외우려고"},{"id":"D","text":"사건을 재현하지 않으려고"}]','A','작성 목적과 수신자를 알면 자료에 담긴 관점과 생략을 더 비판적으로 읽을 수 있습니다.'),
  ('history',2,'고대 문명','문명의 형성과 관련이 큰 조건은 무엇인가요?','[{"id":"A","text":"정착 농업과 잉여 생산"},{"id":"B","text":"문자의 완전한 부재"},{"id":"C","text":"이동만 하는 생활"},{"id":"D","text":"교역의 금지"}]','A','정착과 잉여 생산은 인구 집중, 분업, 정치 조직의 발전을 뒷받침했습니다.'),
  ('history',3,'산업화','산업혁명이 노동에 미친 변화로 알맞은 것은 무엇인가요?','[{"id":"A","text":"공장 중심의 임금 노동 확대"},{"id":"B","text":"도시 인구의 완전한 소멸"},{"id":"C","text":"기계 사용의 중단"},{"id":"D","text":"생산 분업의 축소"}]','A','산업화는 공장제와 기계 생산, 도시로의 노동 이동을 확대했습니다.'),
  ('history',3,'제국주의','제국주의를 분석할 때 함께 살펴야 할 것은 무엇인가요?','[{"id":"A","text":"경제적 이해와 정치·군사적 지배"},{"id":"B","text":"한 인물의 취향만"},{"id":"C","text":"날씨 기록만"},{"id":"D","text":"국경 밖의 모든 자료 배제"}]','A','제국주의는 경제·정치·군사적 지배가 결합된 복합적인 현상으로 분석해야 합니다.'),
  ('history',4,'혁명','혁명의 원인을 설명할 때 가장 설득력 있는 방식은 무엇인가요?','[{"id":"A","text":"구조적 조건과 행위자의 선택을 함께 분석한다"},{"id":"B","text":"단 하나의 원인만 제시한다"},{"id":"C","text":"결과를 원인으로 그대로 바꾼다"},{"id":"D","text":"당시 자료를 사용하지 않는다"}]','A','혁명은 장기 구조와 단기 사건, 다양한 집단의 선택이 상호작용한 결과로 볼 수 있습니다.'),
  ('history',4,'기억과 서술','역사 서술이 하나뿐이 아닐 수 있는 이유는 무엇인가요?','[{"id":"A","text":"자료 선택과 관점에 따라 해석이 달라질 수 있어서"},{"id":"B","text":"과거 사건이 존재하지 않아서"},{"id":"C","text":"모든 기록이 거짓이라서"},{"id":"D","text":"연대가 중요하지 않아서"}]','A','같은 사건도 자료와 질문, 관점에 따라 강조점과 해석이 달라질 수 있습니다.'),
  ('history',5,'비교사','비교사 연구에서 사례를 비교할 때 주의해야 할 점은 무엇인가요?','[{"id":"A","text":"서로 다른 맥락과 개념의 의미를 확인한다"},{"id":"B","text":"모든 사례를 같은 것으로 취급한다"},{"id":"C","text":"차이점을 모두 제거한다"},{"id":"D","text":"자료의 시기를 무시한다"}]','A','비교는 공통 기준을 세우되 각 사회의 맥락과 개념이 다를 수 있음을 고려해야 합니다.'),
  ('history',5,'역사적 인과','역사적 인과관계를 주장할 때 필요한 것은 무엇인가요?','[{"id":"A","text":"시간적 선후와 작동한 연결 고리에 대한 근거"},{"id":"B","text":"두 사건이 비슷해 보인다는 인상만"},{"id":"C","text":"현재의 결과만"},{"id":"D","text":"유명한 사람의 단정"}]','A','인과 주장은 선후 관계뿐 아니라 한 사건이 다른 사건에 영향을 준 경로를 보여야 합니다.'),
  ('literature',1,'문학의 요소','소설에서 사건이 전개되는 시간과 장소를 무엇이라 하나요?','[{"id":"A","text":"배경"},{"id":"B","text":"운율"},{"id":"C","text":"각주"},{"id":"D","text":"목차"}]','A','배경은 이야기가 펼쳐지는 시간적·공간적 조건입니다.'),
  ('literature',1,'화자','작품 속 사건을 전달하는 목소리를 무엇이라 하나요?','[{"id":"A","text":"화자"},{"id":"B","text":"독자"},{"id":"C","text":"출판사"},{"id":"D","text":"편집자"}]','A','화자는 작품의 사건과 생각을 독자에게 전달하는 서술상의 목소리입니다.'),
  ('literature',2,'비유','서로 다른 대상을 직접 견주어 의미를 만드는 표현은 무엇인가요?','[{"id":"A","text":"비유"},{"id":"B","text":"목차"},{"id":"C","text":"인용부호"},{"id":"D","text":"문단 번호"}]','A','비유는 다른 대상의 속성을 빌려 대상을 새롭게 드러내는 표현 방식입니다.'),
  ('literature',2,'시점','1인칭 주인공 시점의 특징은 무엇인가요?','[{"id":"A","text":"주인공이 자신의 경험을 말한다"},{"id":"B","text":"모든 인물의 생각을 항상 안다"},{"id":"C","text":"사건이 일어나지 않는다"},{"id":"D","text":"작가의 이력만 설명한다"}]','A','1인칭 주인공 시점에서는 주인공이 화자가 되어 자신의 경험을 전달합니다.'),
  ('literature',3,'서사 구조','갈등이 서사에서 하는 역할은 무엇인가요?','[{"id":"A","text":"인물의 선택과 사건의 변화를 이끈다"},{"id":"B","text":"모든 사건을 없앤다"},{"id":"C","text":"배경을 고정한다"},{"id":"D","text":"독자의 해석을 금지한다"}]','A','갈등은 인물의 목표와 장애를 만들고 사건을 전개시키는 동력이 됩니다.'),
  ('literature',3,'상징','문학에서 상징은 무엇을 가능하게 하나요?','[{"id":"A","text":"구체적 대상에 더 넓은 의미를 겹쳐 표현한다"},{"id":"B","text":"모든 의미를 하나로 고정한다"},{"id":"C","text":"등장인물을 삭제한다"},{"id":"D","text":"작품의 배경을 숨긴다"}]','A','상징은 구체적인 이미지나 사물에 추상적인 의미를 연결해 표현합니다.'),
  ('literature',4,'해석','문학 작품을 해석할 때 적절한 근거는 무엇인가요?','[{"id":"A","text":"본문의 표현과 구조, 맥락"},{"id":"B","text":"제목만 보고 한 추측"},{"id":"C","text":"작품과 무관한 소문"},{"id":"D","text":"독자의 기분만"}]','A','해석은 본문에 나타난 표현·구조와 작품이 놓인 맥락에 근거해야 설득력을 얻습니다.'),
  ('literature',4,'장르','장르의 관습을 이해하는 것이 독해에 도움 되는 이유는 무엇인가요?','[{"id":"A","text":"독자가 기대와 변주를 파악할 수 있어서"},{"id":"B","text":"모든 작품을 똑같이 읽게 해서"},{"id":"C","text":"작품의 언어를 없애서"},{"id":"D","text":"작가의 선택을 무시해서"}]','A','장르 관습은 독자가 작품의 기대를 파악하고 작가가 그것을 어떻게 변형했는지 보게 합니다.'),
  ('literature',5,'문학과 사회','문학과 사회의 관계를 분석하는 좋은 방법은 무엇인가요?','[{"id":"A","text":"작품의 형식과 시대적 조건을 함께 살핀다"},{"id":"B","text":"작품을 시대와 완전히 분리한다"},{"id":"C","text":"시대 자료만 읽는다"},{"id":"D","text":"작품의 언어를 요약에서 제외한다"}]','A','작품은 시대의 조건을 반영하면서도 고유한 형식과 상상력으로 그것을 재구성합니다.'),
  ('literature',5,'서술의 신뢰성','신뢰할 수 없는 화자를 분석할 때 확인할 것은 무엇인가요?','[{"id":"A","text":"화자의 말과 다른 단서 사이의 불일치"},{"id":"B","text":"화자의 이름 길이"},{"id":"C","text":"책의 가격만"},{"id":"D","text":"문장 수만"}]','A','화자의 진술과 작품 속 다른 단서가 어긋나는 지점을 통해 신뢰성의 문제를 살필 수 있습니다.'),
  ('science',1,'관찰과 가설','과학적 가설은 무엇인가요?','[{"id":"A","text":"검증할 수 있는 잠정적 설명"},{"id":"B","text":"검증이 불가능한 믿음"},{"id":"C","text":"실험 결과의 복사본"},{"id":"D","text":"측정 단위"}]','A','가설은 관찰된 현상을 설명하며 자료로 시험할 수 있는 잠정적 주장입니다.'),
  ('science',1,'측정','측정에서 단위를 사용하는 이유는 무엇인가요?','[{"id":"A","text":"결과를 일정한 기준으로 비교하려고"},{"id":"B","text":"오차를 반드시 없애려고"},{"id":"C","text":"관찰을 대신하려고"},{"id":"D","text":"가설을 숨기려고"}]','A','공통 단위는 서로 다른 측정값을 일관된 기준으로 비교하게 합니다.'),
  ('science',2,'변인','실험에서 독립변인은 무엇인가요?','[{"id":"A","text":"연구자가 변화시키거나 비교하는 요인"},{"id":"B","text":"항상 측정되는 결과"},{"id":"C","text":"실험실의 온도만"},{"id":"D","text":"오차의 이름"}]','A','독립변인은 연구자가 조작하거나 수준을 비교하는 원인 후보입니다.'),
  ('science',2,'생명과학','세포가 생명체의 기본 단위라고 하는 이유는 무엇인가요?','[{"id":"A","text":"생명 활동을 수행하는 구조와 기능을 가지기 때문"},{"id":"B","text":"모든 세포가 같은 모양이기 때문"},{"id":"C","text":"세포에는 물이 없기 때문"},{"id":"D","text":"세포가 관찰되지 않기 때문"}]','A','세포는 물질대사와 유전 등 생명 활동을 수행하는 기본적인 구조적 단위입니다.'),
  ('science',3,'통계','표본을 무작위로 추출하는 목적은 무엇인가요?','[{"id":"A","text":"모집단을 대표할 가능성을 높이려고"},{"id":"B","text":"표본을 항상 크게 만들려고"},{"id":"C","text":"결과를 원하는 대로 만들려고"},{"id":"D","text":"측정을 생략하려고"}]','A','무작위 추출은 특정 집단이 과도하게 선택되는 편향을 줄이고 대표성을 높이는 데 도움이 됩니다.'),
  ('science',3,'에너지','에너지 보존 법칙의 의미는 무엇인가요?','[{"id":"A","text":"에너지는 형태가 바뀌어도 전체량은 보존된다"},{"id":"B","text":"에너지는 항상 사라진다"},{"id":"C","text":"에너지는 생성만 된다"},{"id":"D","text":"열은 에너지가 아니다"}]','A','에너지는 생성되거나 소멸하기보다 다른 형태로 전환되며 전체량이 보존됩니다.'),
  ('science',4,'인과 추론','대조 실험이 과학적 인과 추론에 도움이 되는 이유는 무엇인가요?','[{"id":"A","text":"관심 요인 외 조건을 비교할 수 있어서"},{"id":"B","text":"모든 변인을 제거해서"},{"id":"C","text":"측정 횟수를 1회로 줄여서"},{"id":"D","text":"결과를 관찰하지 않아서"}]','A','대조 조건은 관심 요인의 차이가 결과에 미친 영향을 다른 조건과 비교하게 합니다.'),
  ('science',4,'불확실성','측정값의 오차를 보고해야 하는 이유는 무엇인가요?','[{"id":"A","text":"결과의 불확실성과 재현 가능성을 판단하려고"},{"id":"B","text":"결과를 무조건 무효로 하려고"},{"id":"C","text":"숫자를 장식하려고"},{"id":"D","text":"가설을 증명하지 않으려고"}]','A','오차와 불확실성은 결과가 어느 범위에서 해석되어야 하는지 알려 줍니다.'),
  ('science',5,'과학적 모델','좋은 과학적 모델의 조건으로 알맞은 것은 무엇인가요?','[{"id":"A","text":"현상을 설명하고 새로운 예측을 만들며 한계를 드러낸다"},{"id":"B","text":"모든 현상을 예외 없이 설명한다"},{"id":"C","text":"검증을 거부한다"},{"id":"D","text":"단순한 이름만 제공한다"}]','A','모델은 설명과 예측에 유용해야 하며 적용 범위와 한계를 명확히 해야 합니다.'),
  ('science',5,'재현성','과학에서 재현성이 중요한 이유는 무엇인가요?','[{"id":"A","text":"다른 연구자가 같은 절차로 결과를 확인할 수 있어서"},{"id":"B","text":"한 번의 결과만 믿기 위해서"},{"id":"C","text":"자료 공개를 막기 위해서"},{"id":"D","text":"연구 방법을 바꾸기 위해서"}]','A','재현성은 결과가 우연이나 특정 연구자의 조건에만 의존하지 않는지 확인하게 합니다.'),
  ('ai-tech',1,'알고리즘','알고리즘은 무엇인가요?','[{"id":"A","text":"문제를 해결하기 위한 절차와 규칙"},{"id":"B","text":"컴퓨터의 외관"},{"id":"C","text":"인터넷 주소만"},{"id":"D","text":"저장 장치의 재료"}]','A','알고리즘은 입력을 처리해 결과를 내기 위한 명확한 절차입니다.'),
  ('ai-tech',1,'데이터','데이터의 의미로 가장 알맞은 것은 무엇인가요?','[{"id":"A","text":"관찰·측정·기록된 정보"},{"id":"B","text":"검증할 수 없는 소문만"},{"id":"C","text":"전원 공급 장치"},{"id":"D","text":"화면의 밝기"}]','A','데이터는 현상이나 대상을 관찰·측정·기록한 정보입니다.'),
  ('ai-tech',2,'소프트웨어','소프트웨어와 하드웨어의 관계로 알맞은 것은 무엇인가요?','[{"id":"A","text":"소프트웨어가 하드웨어에서 실행되어 기능을 수행한다"},{"id":"B","text":"둘은 항상 같은 것이다"},{"id":"C","text":"하드웨어는 명령을 실행할 수 없다"},{"id":"D","text":"소프트웨어는 데이터와 무관하다"}]','A','소프트웨어의 명령은 하드웨어 자원을 통해 실행되어 사용자 기능을 제공합니다.'),
  ('ai-tech',2,'네트워크','인터넷에서 패킷은 무엇인가요?','[{"id":"A","text":"전송을 위해 나뉜 데이터 단위"},{"id":"B","text":"모니터의 픽셀"},{"id":"C","text":"암호의 비밀번호"},{"id":"D","text":"프로그램의 오류만"}]','A','데이터는 네트워크에서 전송하기 쉬운 단위인 패킷으로 나뉘어 이동할 수 있습니다.'),
  ('ai-tech',3,'머신러닝','지도학습의 특징은 무엇인가요?','[{"id":"A","text":"입력과 정답이 함께 있는 자료로 학습한다"},{"id":"B","text":"자료를 전혀 사용하지 않는다"},{"id":"C","text":"항상 사람의 규칙만 실행한다"},{"id":"D","text":"결과를 평가할 수 없다"}]','A','지도학습은 입력과 그에 대응하는 정답 라벨을 사용해 예측 관계를 학습합니다.'),
  ('ai-tech',3,'데이터베이스','데이터베이스 인덱스의 주된 목적은 무엇인가요?','[{"id":"A","text":"검색을 빠르게 하는 것"},{"id":"B","text":"모든 데이터를 삭제하는 것"},{"id":"C","text":"비밀번호를 자동 공개하는 것"},{"id":"D","text":"화면을 디자인하는 것"}]','A','인덱스는 특정 조건의 데이터를 더 효율적으로 찾도록 돕는 자료 구조입니다.'),
  ('ai-tech',4,'모델 평가','분류 모델의 정확도만 사용할 때 생길 수 있는 문제는 무엇인가요?','[{"id":"A","text":"클래스 불균형에서 소수 클래스 성능을 가릴 수 있다"},{"id":"B","text":"모든 오류가 사라진다"},{"id":"C","text":"데이터가 필요 없어 진다"},{"id":"D","text":"모델의 목적이 자동으로 바뀐다"}]','A','한 클래스가 매우 많으면 다수 클래스만 맞혀도 정확도가 높아 보일 수 있습니다.'),
  ('ai-tech',4,'보안','다중 인증의 보안상 이점은 무엇인가요?','[{"id":"A","text":"서로 다른 인증 요소를 요구해 한 자격 증명 유출의 위험을 줄인다"},{"id":"B","text":"모든 비밀번호를 없앤다"},{"id":"C","text":"접속 기록을 삭제한다"},{"id":"D","text":"누구나 로그인하게 한다"}]','A','다중 인증은 지식·소유·생체 등 서로 다른 요소를 결합해 단일 정보 유출의 영향을 줄입니다.'),
  ('ai-tech',5,'AI 편향','AI 시스템의 편향을 줄이려면 무엇을 해야 하나요?','[{"id":"A","text":"데이터와 결과를 집단별로 점검하고 원인을 개선한다"},{"id":"B","text":"모든 평가를 생략한다"},{"id":"C","text":"결과를 무조건 사람보다 우선한다"},{"id":"D","text":"오류 사례를 숨긴다"}]','A','편향은 데이터 구성과 설계·사용 맥락에서 생길 수 있으므로 결과를 집단별로 점검해야 합니다.'),
  ('ai-tech',5,'기술과 사회','기술 시스템의 책임성을 높이는 방법은 무엇인가요?','[{"id":"A","text":"의사결정 과정과 한계, 이의 제기 절차를 공개한다"},{"id":"B","text":"자동화 결과를 설명하지 않는다"},{"id":"C","text":"사용자에게 책임을 전부 넘긴다"},{"id":"D","text":"감사를 금지한다"}]','A','설명 가능성·감사·이의 제기 절차는 기술 시스템의 책임 있는 사용을 돕습니다.')
) as q(slug, level, topic, question, options, correct_option, explanation) on q.slug = c.slug
where not exists (
  select 1 from public.assessment_questions existing
  where existing.category_id = c.id and existing.question = q.question
);
